sys_ui_action.script:
(function() {
    var checkinTable = 'x_2023506_german_1_ret_chkin';
    var checkin = new GlideRecord(checkinTable);
    checkin.addQuery('u_retention_case', current.getUniqueValue());
    checkin.addQuery('u_milestone', '30_days');
    checkin.setLimit(1);
    checkin.query();

    if (checkin.next()) {
        // 1. Update Check-in status and date
        checkin.setValue('u_status', 'sent');
        var today = new GlideDate();
        checkin.setValue('u_due_date', today.getValue());
        checkin.update();

        // 2. Generate direct dynamic portal survey link
        var instanceUrl = gs.getProperty('glide.servlet.uri');
        var pageId = 'gvft_retention_checkin'; // Your Service Portal page ID
        var portalLink = instanceUrl + 'sp?id=' + pageId + '&sys_id=' + checkin.getUniqueValue();

        // 3. Fire the event: Parm1 = Candidate Email, Parm2 = Direct Link
        var candidateEmail = current.getValue('u_candidate_email');
        gs.eventQueue('x_2023506_german_1.retention.30day.send', checkin, candidateEmail, portalLink);

        gs.addInfoMessage('Day 30 check-in activated. Invitation email dispatched to ' + candidateEmail + '.');
    } else {
        gs.addErrorMessage('No Day 30 check-in record found for this Retention Case.');
    }

    action.setRedirectURL(current);
})();
